// Mock WhatsApp notification via n8n Code node
// Replace this with the actual WhatsApp/Twilio/360dialog node
const screening = $('Screen Candidate').item.json.screening;
const github = $('Screen Candidate').item.json.github_data;
const questions = $('Generate Screening Questions').item.json.questions;

const message = [
  `🎯 *HireMind Alert - New Shortlisted Candidate*`,
  ``,
  `📋 Score: ${screening.score}/100 (${screening.recommendation})`,
  `✅ Skills: ${screening.skills_found.slice(0, 5).join(', ')}`,
  `🐙 GitHub: ${github.profile_url || 'N/A'} (${github.public_repos || 0} repos)`,
  `📊 Languages: ${(github.top_languages || []).join(', ')}`,
  ``,
  `❓ Screening Questions:`,
  ...questions.map((q, i) => `${i+1}. ${q.question}`),
  ``,
  `💡 Reason: ${screening.reason}`,
].join('\n');

console.log('[HireMind WhatsApp MOCK]\n' + message);

return [
  {
    json: {
      whatsapp_status: 'mocked',
      message_preview: message.substring(0, 200),
      recipient: 'hiring-team@startup.com',
      note: 'Replace this node with WhatsApp/Twilio node and set recipient number'
    }
  }
];

// Candidate not shortlisted — log for record keeping
const screening = $('Screen Candidate').item.json.screening;
console.log(`[HireMind] Candidate not shortlisted. Score: ${screening.score}. Reason: ${screening.reason}`);
return [{ json: { status: 'not_shortlisted', score: screening.score } }];
